'use strict';
const HUDDLE={view:'sessions',tab:'attendees',dataUnit:'',room:null,context:null,config:null,configLoading:false,sessions:[],error:'',busy:false,acting:false,refreshing:false,epoch:0,poll:null,lobbyPoll:null,listLoading:false,refreshTimer:null,attachments:new Map(),sdkPromise:null,key:'',code:'',title:'',selectedSession:'',selectedTitle:'',data:null,chatSignature:'',panelSignature:'',sessionRevision:0,pendingCode:'',pendingSession:'',loaded:false,databaseReady:false,permissions:null,setupRequired:false};
const huddleCanHost=()=>['Admin','DM','BM','Staff','BC'].includes(S.role)&&hasWorkspaceAccess();
const huddleCanJoin=()=>hasWorkspaceAccess()&&S.me?.onboarding_complete!==false&&(isStaff()||S.me?.registration_kind==='Member'&&S.me?.membership_status==='Active');
const huddleKey=()=>JSON.stringify([S.session?.user?.id,S.role,S.assignment?.branch_id,S.assignment?.district,S.me?.branch_id,S.me?.membership_status,S.me?.registration_kind]);
function huddleMessage(error){return S.role==='Admin'?error.message:error.setupRequired?'Your administrator needs to apply the Huddle database update. Then refresh Sessions.':/setup|migration|configured|credentials|awaiting.*connection/i.test(error.message)?'OCCCI Huddle is being set up. Please contact an administrator.':error.message;}
async function huddleApi(action,data={}){await ensureSession();const response=await fetch('/api/huddle',{method:'POST',headers:{Authorization:'Bearer '+S.session.access_token,'Content-Type':'application/json'},body:JSON.stringify({action,...data}),cache:'no-store'});const result=await response.json().catch(()=>({}));if(!response.ok){const error=Error(result.error||'Huddle could not complete this action.');error.status=response.status;error.setupRequired=result.setupRequired===true;throw error;}return result;}
function huddleUnitOptions(){const branches=allowedBranches();return (S.role==='Admin'?'<option value="G">All cooperative units</option>':'')+(['Admin','DM'].includes(S.role)?[...new Set(branches.map(b=>b.district))].sort().map(d=>`<option value="D:${d}">District ${d}</option>`).join(''):'')+[...new Set(branches.map(b=>b.district))].sort().map(d=>`<optgroup label="District ${d}">${branches.filter(b=>b.district===d).map(b=>`<option value="B:${e(b.id)}">${e(b.name)} Branch</option>`).join('')}</optgroup>`).join('');}
function huddleUnitControl(){if(['BM','Staff','BC'].includes(S.role))return `<label>Operating unit<input readonly value="${e(bn(S.assignment.branch_id))} Branch"><input type="hidden" name="unit" value="B:${e(S.assignment.branch_id)}"></label>`;const options=huddleUnitOptions().replace('<option value="G">All cooperative units</option>','');return `<label>Operating unit<select name="unit" onchange="HUDDLE.dataUnit=this.value">${options}</select></label>`;}
function huddleUnit(value){return value?.startsWith('B:')?{branch:value.slice(2),district:null}:value?.startsWith('D:')?{branch:null,district:Number(value.slice(2))}:{branch:null,district:null};}
function huddleUnitLabel(){return 'Open to OCCCI accounts with the session code';}
function huddleCode(code){return (code||'').replace(/(.{5})(.{5})/,'$1-$2');}
function huddleOpenSessions(){if(!huddleCanJoin())return;HUDDLE.view='sessions';go('Huddle');}
function huddleReturn(){if(!HUDDLE.room)return;HUDDLE.view='meeting';go('Huddle');}
function huddleActiveSessions(){return HUDDLE.sessions.filter(s=>s.status==='Active'&&Date.parse(s.expires_at)>Date.now());}
function huddleSessionCards(){
 const sessions=huddleActiveSessions();
 if(!sessions.length)return `<div class="huddle-session-empty">${icon('video')}<strong>${HUDDLE.configLoading?'Loading sessions…':'No active sessions'}</strong><p>${huddleCanHost()?'Create a session above to generate its invitation code.':'A session will appear here when an OCCCI host creates it.'}</p></div>`;
 return sessions.map(s=>`<article class="huddle-session-card"><button type="button" class="huddle-session-open" data-huddle-session="${e(s.id)}" onclick="huddleJoinDialog(this.dataset.huddleSession)"><span class="huddle-session-icon">${icon('video')}</span><span class="huddle-session-info"><span class="huddle-session-status">Active session${s.is_host?' · Your session':''}</span><strong>${e(s.title)}</strong><span>Host: ${e(s.host_name||'OCCCI host')}</span><time datetime="${e(s.created_at)}">${e(new Date(s.created_at).toLocaleString('en-PH',{month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'}))}</time></span><span class="huddle-session-enter">${icon('shield')}<span>Enter code</span></span></button>${s.is_host&&s.join_code?`<div class="huddle-session-host"><span>Code <strong>${e(huddleCode(s.join_code))}</strong></span><div><button type="button" class="outline small" data-huddle-session="${e(s.id)}" onclick="huddleCopySessionInvite(this.dataset.huddleSession)" aria-label="Copy invitation for ${e(s.title)}">Copy invitation</button><button type="button" class="danger small" data-huddle-session="${e(s.id)}" onclick="huddleEndDialog(this.dataset.huddleSession)" aria-label="End ${e(s.title)}">End</button></div></div>`:''}</article>`).join('');
}
function huddleView(){
 if(HUDDLE.room&&HUDDLE.context&&HUDDLE.view==='meeting')return huddleMeetingView();
 return heading('OCCCI Huddle','Create a session, share its code, and meet together.',`<button type="button" class="outline small" onclick="huddleJoinDialog()">${icon('shield')}Join with code</button>`)+`<section class="huddle-lobby">${HUDDLE.room?`<div class="huddle-current-call">${icon('video')}<span>You are in <strong>${e(HUDDLE.context.session.title)}</strong></span><button type="button" class="outline small" onclick="huddleReturn()">Return to call</button></div>`:''}${huddleCanHost()?`<article class="card huddle-create"><div><h2>Create a session</h2><p>A unique code is generated for every session.</p></div><form onsubmit="event.preventDefault();huddleCreate(this)"><label class="sr-only" for="huddleSessionTitle">Session title</label><input id="huddleSessionTitle" name="title" required maxlength="150" value="${e(HUDDLE.title)}" placeholder="Session title" oninput="HUDDLE.title=this.value"><button type="submit" class="primary" ${!HUDDLE.databaseReady||HUDDLE.permissions?.can_host!==true||HUDDLE.busy?'disabled':''}>${icon('plus')}${HUDDLE.busy?'Creating…':'Create session'}</button></form></article>`:''}<p class="form-error" data-huddle-lobby-error role="alert" ${!HUDDLE.error?'hidden':''}>${e(HUDDLE.error)}</p><p class="hint" data-huddle-setup-help ${!HUDDLE.setupRequired?'hidden':''}>${S.role==='Admin'?'<a href="huddle-setup.sql?v=50" download="OCCCI-Huddle-Update.sql">Download the required Huddle SQL update</a> and run it in Supabase SQL Editor. Then select Refresh.':'Ask an administrator to apply the Huddle database update, then select Refresh.'}</p>${HUDDLE.loaded&&!HUDDLE.config?.configured?'<p class="huddle-setup" role="status">Audio and video are awaiting the conference service connection. You can create and share sessions once the session database is ready.</p>':''}<section class="card huddle-session-panel" aria-labelledby="huddleSessionsTitle"><div class="huddle-panel-heading"><div><h2 id="huddleSessionsTitle">Sessions <span class="huddle-session-count" data-huddle-count>${huddleActiveSessions().length}</span></h2><p>Tap a session, then enter the code provided by its host.</p></div><button type="button" class="outline small" onclick="huddleRefreshSessions()" aria-label="Refresh Huddle sessions">${icon('switch')}Refresh</button></div><div class="huddle-session-grid" data-huddle-session-grid>${huddleSessionCards()}</div></section></section>`;
}
function huddleUpdateSessionPanel(){const grid=document.querySelector('[data-huddle-session-grid]'),signature=JSON.stringify(huddleActiveSessions());if(grid&&signature!==HUDDLE.panelSignature){const focused=document.activeElement?.dataset?.huddleSession;grid.innerHTML=huddleSessionCards();HUDDLE.panelSignature=signature;if(focused)[...grid.querySelectorAll('[data-huddle-session]')].find(n=>n.dataset.huddleSession===focused)?.focus({preventScroll:true});}const count=document.querySelector('[data-huddle-count]');if(count)count.textContent=huddleActiveSessions().length;const error=document.querySelector('[data-huddle-lobby-error]');if(error){error.textContent=HUDDLE.error;error.hidden=!HUDDLE.error;}const help=document.querySelector('[data-huddle-setup-help]');if(help)help.hidden=!HUDDLE.setupRequired;const create=document.querySelector('.huddle-create button[type=submit]');if(create)create.disabled=!HUDDLE.databaseReady||HUDDLE.permissions?.can_host!==true||HUDDLE.busy;}
function huddleJoinDialog(sessionId='',legacyCode=''){
 if(!huddleCanJoin()||HUDDLE.busy)return;
 if(HUDDLE.room){if(sessionId===HUDDLE.context.session.id)huddleReturn();else toast('Leave your current Huddle before joining another session.');return;}
 const session=HUDDLE.sessions.find(s=>s.id===sessionId);
 HUDDLE.selectedSession=sessionId;HUDDLE.selectedTitle=session?.title||'OCCCI Huddle';HUDDLE.code=legacyCode;
 openModal(session?.title||'Join OCCCI Huddle',`<form class="huddle-join-form" onsubmit="event.preventDefault();huddleJoin(this)"><p>${session?'Enter the special code for this session.':'Enter the special code provided by your host.'}</p><label>Session code<input name="code" value="${e(legacyCode)}" required maxlength="24" autocomplete="off" autocapitalize="characters" placeholder="Enter session code" oninput="HUDDLE.code=this.value"></label><div class="huddle-preferences"><label><input type="checkbox" name="mic">Turn on my microphone when joining</label><label><input type="checkbox" name="camera">Turn on my camera when joining</label></div>${!HUDDLE.config?.configured?'<p class="huddle-setup">Audio and video will be available once the conference service is connected.</p>':''}<button type="submit" class="primary" ${!HUDDLE.config?.configured||HUDDLE.busy?'disabled':''}>${icon('video')}Join session</button><p class="hint">Your microphone and camera stay off unless you choose to enable them.</p></form>`,{className:'huddle-join-dialog'});
 setTimeout(()=>document.querySelector('.huddle-join-form input[name=code]')?.focus(),0);
}
function huddleMeetingView(){const c=HUDDLE.context,host=c.is_host;
 return `<section class="huddle-meeting"><div class="huddle-meeting-heading"><div><span class="huddle-brand">${icon('video')} OCCCI Huddle</span><h1>${e(c.session.title)}</h1><p>${e(huddleUnitLabel())} · <span data-huddle-connection>Connected</span></p></div><div class="huddle-code-actions">${host?`<strong>${e(huddleCode(c.session.join_code))}</strong><button type="button" class="outline small" onclick="huddleCopyInvite()">Copy invitation</button>`:''}<button type="button" class="outline small" onclick="huddleOpenSessions()">Sessions</button>${host?'<button type="button" class="danger small" onclick="huddleEndDialog()">End session</button>':''}</div></div><p class="huddle-room-error" data-huddle-error role="alert" hidden></p><div class="huddle-workspace"><div class="huddle-stage"><div class="huddle-screen-stage" data-huddle-screens hidden></div><div class="huddle-video-grid" data-huddle-people></div><div class="huddle-controls"><button type="button" class="outline" data-huddle-control="mic" onclick="huddleToggle('mic')">${icon('mic')}<span>Microphone</span></button><button type="button" class="outline" data-huddle-control="camera" onclick="huddleToggle('camera')">${icon('camera')}<span>Camera</span></button><button type="button" class="outline" data-huddle-control="screen" onclick="huddleToggle('screen')">${icon('share')}<span>Share screen</span></button><button type="button" class="outline" data-huddle-audio onclick="huddleStartAudio()" hidden>Enable sound</button><button type="button" class="danger" onclick="huddleLeave()">Leave</button></div><p class="huddle-mic-note" data-huddle-mic-note role="status"></p></div><aside class="huddle-collaboration card"><div class="tabs huddle-tabs"><button type="button" data-huddle-tab="attendees" class="active" onclick="huddleTab('attendees')">Attendees</button><button type="button" data-huddle-tab="chat" onclick="huddleTab('chat')">Chat</button>${isStaff()?'<button type="button" data-huddle-tab="data" onclick="huddleTab(\'data\')">Data panel</button>':''}</div><section data-huddle-pane="attendees">${host?'<div class="huddle-host-controls"><button type="button" class="outline small" onclick="huddleModerate(\'mute_all\')">Mute all</button><button type="button" class="outline small" onclick="huddleModerate(\'allow_all\')">Allow microphones</button></div>':''}<div data-huddle-roster></div></section><section data-huddle-pane="chat" hidden><div class="huddle-chat-list" data-huddle-chat aria-live="polite"></div><form class="huddle-chat-form" onsubmit="event.preventDefault();huddleSendChat(this)"><label class="sr-only" for="huddleChatInput">Message</label><textarea id="huddleChatInput" name="message" placeholder="Message this Huddle" required maxlength="2000" rows="2"></textarea><button type="submit" class="primary small">Send</button></form></section>${isStaff()?`<section data-huddle-pane="data" hidden><h2>Operating unit data</h2><p class="hint">Shared cards remain visible to staff authorized for that district or branch.</p><form class="huddle-data-form" onsubmit="event.preventDefault();huddleLoadData(this)">${huddleUnitControl('data')}<button type="submit" class="outline small">Load verified data</button></form><div data-huddle-data></div><h3 class="huddle-shared-title">Shared data cards</h3><div data-huddle-shared></div></section>`:''}</aside></div></section>`;
}
async function huddleSdk(){if(window.LivekitClient)return window.LivekitClient;if(!HUDDLE.sdkPromise)HUDDLE.sdkPromise=new Promise((resolve,reject)=>{const script=document.createElement('script');script.src='https://cdn.jsdelivr.net/npm/livekit-client@2.22.4/dist/livekit-client.umd.min.js';script.onload=()=>{if(window.LivekitClient)resolve(window.LivekitClient);else{HUDDLE.sdkPromise=null;script.remove();reject(Error('The meeting library could not be loaded.'));}};script.onerror=()=>{HUDDLE.sdkPromise=null;script.remove();reject(Error('The meeting library could not be loaded. Check your connection.'));};document.head.append(script);});return HUDDLE.sdkPromise;}
async function huddleLoadLobby(){
 if(HUDDLE.configLoading||!huddleCanJoin())return;HUDDLE.configLoading=true;const epoch=HUDDLE.epoch,key=huddleKey();HUDDLE.key=key;
 try{const response=await fetch('/api/huddle',{cache:'no-store'});if(!response.ok)throw Error('Conference service is not available yet.');const config=await response.json();let sessions=[],error='',ready=false,permissions=null,setupRequired=false;try{const result=await huddleApi('list');sessions=result.sessions;permissions=result.permissions;ready=permissions?.database_ready===true;}catch(e){error=huddleMessage(e);setupRequired=e.setupRequired===true;}if(epoch!==HUDDLE.epoch||key!==huddleKey())return;HUDDLE.config=config;HUDDLE.sessions=sessions;HUDDLE.databaseReady=ready;HUDDLE.permissions=permissions;HUDDLE.setupRequired=setupRequired;HUDDLE.error=error;HUDDLE.loaded=true;}
 catch(error){if(epoch===HUDDLE.epoch){HUDDLE.error=huddleMessage(error);HUDDLE.loaded=true;}}
 finally{if(epoch===HUDDLE.epoch){HUDDLE.configLoading=false;if(S.page==='Huddle'&&HUDDLE.view==='sessions')render();huddleOpenPendingInvitation();}}
}
async function huddleRefreshSessions(){
 if(!huddleCanJoin()||HUDDLE.listLoading||HUDDLE.configLoading)return;if(!HUDDLE.loaded||!HUDDLE.databaseReady)return huddleLoadLobby();
 HUDDLE.listLoading=true;const epoch=HUDDLE.epoch,key=huddleKey(),revision=HUDDLE.sessionRevision;try{const result=await huddleApi('list');if(epoch!==HUDDLE.epoch||key!==huddleKey()||revision!==HUDDLE.sessionRevision)return;HUDDLE.sessions=result.sessions;HUDDLE.permissions=result.permissions;HUDDLE.databaseReady=result.permissions?.database_ready===true;HUDDLE.setupRequired=false;HUDDLE.error='';huddleUpdateSessionPanel();}catch(error){if(epoch===HUDDLE.epoch){HUDDLE.error=huddleMessage(error);HUDDLE.setupRequired=error.setupRequired===true;if(HUDDLE.setupRequired){HUDDLE.databaseReady=false;HUDDLE.permissions=null;clearInterval(HUDDLE.lobbyPoll);HUDDLE.lobbyPoll=null;}huddleUpdateSessionPanel();}}finally{if(epoch===HUDDLE.epoch)HUDDLE.listLoading=false;}
}
function huddleOpenPendingInvitation(){if(!huddleCanJoin()||!HUDDLE.loaded||!HUDDLE.pendingCode&&!HUDDLE.pendingSession)return;const code=HUDDLE.pendingCode,sid=HUDDLE.pendingSession;HUDDLE.pendingCode='';HUDDLE.pendingSession='';HUDDLE.view='sessions';go('Huddle');huddleJoinDialog(sid,code);}
function huddleBeforeRender(){if(HUDDLE.key&&(HUDDLE.key!==huddleKey()||!huddleCanJoin()))huddleReset();}
function huddleMount(){
 if(HUDDLE.room&&(HUDDLE.key!==huddleKey()||!huddleCanJoin()))huddleReset();
 if((HUDDLE.pendingCode||HUDDLE.pendingSession)&&huddleCanJoin()&&S.page!=='Huddle'){HUDDLE.view='sessions';S.page='Huddle';render();return;}
 const container=document.querySelector('.huddle-meeting');
 huddleDetachMissing();
 if(HUDDLE.room){huddleDock();if(container){huddleUpdatePeople();huddleUpdateCollaboration();huddleSyncTracks();huddleUpdateControls();huddleTab(HUDDLE.tab);const unit=container.querySelector('.huddle-data-form select');if(unit&&[...unit.options].some(o=>o.value===HUDDLE.dataUnit))unit.value=HUDDLE.dataUnit;}}
 if(S.page==='Huddle'&&HUDDLE.view==='sessions'&&huddleCanJoin()){
  HUDDLE.panelSignature=JSON.stringify(huddleActiveSessions());
  if(!HUDDLE.loaded&&!HUDDLE.configLoading)huddleLoadLobby();
  if(HUDDLE.loaded&&HUDDLE.databaseReady&&!HUDDLE.lobbyPoll){HUDDLE.lobbyPoll=setInterval(huddleRefreshSessions,12000);huddleRefreshSessions();}
  if(HUDDLE.loaded)huddleOpenPendingInvitation();
 }else{clearInterval(HUDDLE.lobbyPoll);HUDDLE.lobbyPoll=null;}
}
function huddleDock(){let dock=document.getElementById('huddleDock');if(!dock){dock=document.createElement('div');dock.id='huddleDock';dock.className='huddle-dock';document.body.append(dock);}dock.hidden=S.page==='Huddle'&&HUDDLE.view==='meeting'||!HUDDLE.room;dock.innerHTML=`${icon('video')}<span>In OCCCI Huddle</span><button type="button" onclick="huddleReturn()">Return</button><button type="button" onclick="huddleLeave()">Leave</button>`;}
async function huddleCreate(form){
 if(!huddleCanHost()||!HUDDLE.databaseReady||HUDDLE.permissions?.can_host!==true||HUDDLE.busy)return;HUDDLE.busy=true;HUDDLE.error='';const epoch=HUDDLE.epoch,key=huddleKey(),title=form.elements.title.value;HUDDLE.key=key;const button=form.querySelector('button[type=submit]');button.disabled=true;button.textContent='Creating…';
 try{const result=await huddleApi('create',{title});if(epoch!==HUDDLE.epoch||key!==huddleKey())return;const session={...result.session,host_name:S.me.full_name,is_host:true,attendees:0};HUDDLE.sessions=[session,...HUDDLE.sessions.filter(s=>s.id!==session.id)];HUDDLE.sessionRevision++;HUDDLE.title='';HUDDLE.busy=false;HUDDLE.view='sessions';if(S.page==='Huddle'){render();huddleCreatedDialog(session);}else toast('Huddle session created. Open Sessions to copy its code.');}
 catch(error){if(epoch===HUDDLE.epoch){HUDDLE.error=huddleMessage(error);HUDDLE.setupRequired=error.setupRequired===true;if(HUDDLE.setupRequired){HUDDLE.databaseReady=false;HUDDLE.permissions=null;clearInterval(HUDDLE.lobbyPoll);HUDDLE.lobbyPoll=null;}huddleUpdateSessionPanel();}}
 finally{if(epoch===HUDDLE.epoch){HUDDLE.busy=false;button.disabled=!HUDDLE.databaseReady||HUDDLE.permissions?.can_host!==true;button.innerHTML=icon('plus')+'Create session';huddleUpdateSessionPanel();}}
}
function huddleCreatedDialog(session){const invite=huddleInvitationUrl(session);openModal('Session created',`<div class="huddle-created"><p><strong>${e(session.title)}</strong> is now on the Sessions panel. Share this code with attendees.</p><label>Generated session code<input readonly value="${e(huddleCode(session.join_code))}" onclick="this.select()"></label><label>Session portal<input readonly value="${e(invite)}" onclick="this.select()"></label><div class="huddle-invite-actions"><button type="button" class="primary" data-huddle-session="${e(session.id)}" onclick="huddleCopySessionInvite(this.dataset.huddleSession)">Copy invitation</button><button type="button" class="outline" onclick="closeModal()">Done</button></div></div>`,{className:'huddle-join-dialog'});}
async function huddleJoin(form){await huddleConnect('join',{code:form.elements.code.value,sessionId:HUDDLE.selectedSession||null},form.elements.mic.checked,form.elements.camera.checked);}
async function huddleConnect(action,data,mic,camera){
 if(HUDDLE.busy||HUDDLE.room)return;HUDDLE.busy=true;HUDDLE.error='';const epoch=HUDDLE.epoch,key=huddleKey();HUDDLE.key=key;const button=document.querySelector('.huddle-join-form button[type=submit]');if(button){button.disabled=true;button.textContent='Connecting…';}const message=document.getElementById('actionMessage');if(message)message.textContent='';let room;
 try{const sdk=await huddleSdk(),joined=await huddleApi(action,data);if(epoch!==HUDDLE.epoch||key!==huddleKey())return;
  room=new sdk.Room({adaptiveStream:true,dynacast:true,videoCaptureDefaults:{resolution:sdk.VideoPresets.h720.resolution}});HUDDLE.room=room;HUDDLE.context=joined.context;HUDDLE.key=key;HUDDLE.data=null;HUDDLE.chatSignature='';
  const update=()=>{if(HUDDLE.room===room){huddleUpdatePeople();huddleSyncTracks();huddleUpdateControls();}};
  for(const name of ['ParticipantConnected','ParticipantDisconnected','TrackSubscribed','TrackUnsubscribed','TrackMuted','TrackUnmuted','LocalTrackPublished','LocalTrackUnpublished','ParticipantNameChanged','ParticipantPermissionsChanged'])if(sdk.RoomEvent[name])room.on(sdk.RoomEvent[name],update);
  room.on(sdk.RoomEvent.ActiveSpeakersChanged,speakers=>{const active=new Set(speakers.map(p=>p.identity));document.querySelectorAll('[data-huddle-person]').forEach(tile=>tile.classList.toggle('is-speaking',active.has(tile.dataset.huddlePerson)));});
  room.on(sdk.RoomEvent.DataReceived,(_payload,_sender,_kind,topic)=>{if(topic==='occci.huddle.changed')huddleScheduleRefresh();});
  room.on(sdk.RoomEvent.ConnectionStateChanged,()=>huddleUpdateControls());room.on(sdk.RoomEvent.AudioPlaybackStatusChanged,()=>huddleUpdateControls());
  room.on(sdk.RoomEvent.Disconnected,()=>{if(HUDDLE.room===room){huddleReset();if(S.page==='Huddle'){HUDDLE.error='You left the Huddle or the session ended.';render();}}});
  await room.connect(joined.url,joined.token);if(epoch!==HUDDLE.epoch||key!==huddleKey()){await room.disconnect();return;}
  S.page='Huddle';HUDDLE.view='meeting';HUDDLE.busy=false;closeModal();HUDDLE.code='';HUDDLE.selectedSession='';render();HUDDLE.poll=setInterval(()=>huddleRefresh(),12000);
  for(const [enable,kind] of [[mic&&!joined.context.mic_locked,'mic'],[camera,'camera']])if(enable)await huddleSetMedia(kind,true);
 }catch(error){if(epoch===HUDDLE.epoch){if(HUDDLE.room){const failed=HUDDLE.context?.session.id;huddleReset();closeModal();HUDDLE.error=huddleMessage(error);if(S.page==='Huddle')render();if(failed)huddleApi('leave',{sessionId:failed}).catch(()=>{});}else room?.disconnect();if(message)message.textContent=huddleMessage(error);HUDDLE.busy=false;}}
 finally{if(epoch===HUDDLE.epoch)HUDDLE.busy=false;if(button?.isConnected){button.disabled=!HUDDLE.config?.configured;button.innerHTML=icon('video')+'Join session';}}
}
function huddleDetachMissing(){for(const [key,item] of HUDDLE.attachments)if(!item.element.isConnected){item.track.detach(item.element);HUDDLE.attachments.delete(key);}}
function huddleSyncTracks(){const room=HUDDLE.room,sdk=window.LivekitClient;if(!room||!sdk)return;const desired=new Set();let audio=document.getElementById('huddleAudio');if(!audio){audio=document.createElement('div');audio.id='huddleAudio';audio.hidden=true;document.body.append(audio);}const screen=document.querySelector('[data-huddle-screens]');
 for(const p of [room.localParticipant,...room.remoteParticipants.values()]){
  const local=p===room.localParticipant;
  for(const [source,target] of [[sdk.Track.Source.Camera,'camera'],[sdk.Track.Source.ScreenShare,'screen']]){
   const pub=p.getTrackPublication(source);if(!pub?.track||pub.isMuted)continue;let container;
   if(target==='camera')container=[...document.querySelectorAll('[data-huddle-camera]')].find(n=>n.dataset.huddleCamera===p.identity);
   else if(screen){container=[...screen.children].find(n=>n.dataset.huddleScreen===p.identity);if(!container){container=document.createElement('div');container.className='huddle-screen';container.dataset.huddleScreen=p.identity;container.innerHTML=`<strong>${e(p.name||'Participant')} is sharing</strong>`;screen.append(container);}}
   if(!container)continue;const key=p.identity+':'+target+':'+pub.track.sid;desired.add(key);
   if(!HUDDLE.attachments.has(key)){const element=pub.track.attach();element.autoplay=true;element.playsInline=true;element.muted=local;element.classList.toggle('is-local',local&&target==='camera');container.append(element);HUDDLE.attachments.set(key,{track:pub.track,element});}
   container.classList.add('has-video');
  }
  if(!local)for(const pub of p.audioTrackPublications.values())if(pub.track){const key=p.identity+':audio:'+pub.track.sid;desired.add(key);if(!HUDDLE.attachments.has(key)){const element=pub.track.attach();element.autoplay=true;audio.append(element);HUDDLE.attachments.set(key,{track:pub.track,element});}}
 }
 for(const [key,item] of HUDDLE.attachments)if(!desired.has(key)){item.track.detach(item.element);item.element.remove();HUDDLE.attachments.delete(key);}
 document.querySelectorAll('[data-huddle-camera]').forEach(n=>n.classList.toggle('has-video',Boolean(n.querySelector('video'))));
 if(screen){for(const n of [...screen.children])if(!n.querySelector('video'))n.remove();screen.hidden=!screen.children.length;}
}
function huddleUpdatePeople(){const root=document.querySelector('[data-huddle-people]'),room=HUDDLE.room,c=HUDDLE.context;if(!root||!room||!c)return;const people=[room.localParticipant,...room.remoteParticipants.values()],ids=new Set(people.map(p=>p.identity));
 for(const tile of [...root.children])if(!ids.has(tile.dataset.huddlePerson))tile.remove();
 for(const p of people){let tile=[...root.children].find(n=>n.dataset.huddlePerson===p.identity);if(!tile){tile=document.createElement('article');tile.className='huddle-person';tile.dataset.huddlePerson=p.identity;tile.innerHTML=`<div class="huddle-camera" data-huddle-camera="${e(p.identity)}"><span class="huddle-initials"></span></div><div class="huddle-person-label"><strong></strong><span></span></div>`;root.append(tile);}const name=c.participants.find(a=>a.user_id===p.identity)?.name||p.name||'Participant';tile.querySelector('.huddle-initials').textContent=name.split(' ').filter(Boolean).slice(0,2).map(n=>n[0]).join('');tile.querySelector('strong').textContent=name+(p===room.localParticipant?' (You)':'');tile.querySelector('.huddle-person-label span').innerHTML=icon(p.isMicrophoneEnabled?'mic':'micOff');}
 const roster=document.querySelector('[data-huddle-roster]');if(roster)roster.innerHTML=people.map(p=>{const info=c.participants.find(a=>a.user_id===p.identity),host=p.identity===c.session.host_id;return `<div class="huddle-attendee"><div><strong>${e(info?.name||p.name||'Participant')}</strong><small>${e(host?'Host':roleLabel(info?.role||'Member'))}${info?.mic_locked?' · Microphone restricted':''}</small></div>${c.is_host&&!host?`<button type="button" class="outline small" data-huddle-target="${e(p.identity)}" onclick="huddleModerate('${info?.mic_locked?'allow':'mute'}',this.dataset.huddleTarget)">${info?.mic_locked?'Allow':'Mute'}</button>`:''}</div>`;}).join('');
 huddleDetachMissing();
}
function huddleUpdateControls(){const room=HUDDLE.room,c=HUDDLE.context;if(!room||!c)return;const local=room.localParticipant;for(const [kind,enabled,label] of [['mic',local.isMicrophoneEnabled,'Microphone'],['camera',local.isCameraEnabled,'Camera'],['screen',local.isScreenShareEnabled,'Screen sharing']]){const b=document.querySelector(`[data-huddle-control="${kind}"]`);if(b){b.classList.toggle('is-on',enabled);b.setAttribute('aria-pressed',String(enabled));b.disabled=HUDDLE.acting||room.state!=='connected'||kind==='mic'&&c.mic_locked;b.querySelector('span').textContent=kind==='mic'&&c.mic_locked?'Host muted':enabled?(kind==='screen'?'Stop sharing':label+' on'):(kind==='screen'?'Share screen':label+' off');}}
 const note=document.querySelector('[data-huddle-mic-note]');if(note)note.textContent=c.mic_locked?'Your host has restricted the microphone. Wait for permission to turn it on.':'You control your camera and microphone. Allowing a microphone does not turn it on automatically.';
 const status=document.querySelector('[data-huddle-connection]');if(status)status.textContent=room.state==='connected'?'Connected':room.state==='reconnecting'?'Reconnecting…':'Connecting…';const audio=document.querySelector('[data-huddle-audio]');if(audio)audio.hidden=room.canPlaybackAudio!==false;
}
function huddleShowError(error){const node=document.querySelector('[data-huddle-error]');if(node){node.hidden=false;node.textContent=huddleMessage(error);}else toast(huddleMessage(error));}
async function huddleSetMedia(kind,on){const room=HUDDLE.room;if(!room)return;try{if(kind==='mic'&&!HUDDLE.context.mic_locked)await room.localParticipant.setMicrophoneEnabled(on);else if(kind==='camera')await room.localParticipant.setCameraEnabled(on);else if(kind==='screen')await room.localParticipant.setScreenShareEnabled(on);huddleUpdatePeople();huddleSyncTracks();huddleUpdateControls();}catch(error){huddleShowError(Error(error.name==='NotAllowedError'?'Permission was not granted. Allow microphone/camera access in your browser, or choose a screen to share.':error.message||'This device cannot share its screen.'));}}
function huddleToggle(kind){const p=HUDDLE.room?.localParticipant;if(!p)return;return huddleSetMedia(kind,!(kind==='mic'?p.isMicrophoneEnabled:kind==='camera'?p.isCameraEnabled:p.isScreenShareEnabled));}
function huddleStartAudio(){HUDDLE.room?.startAudio().then(huddleUpdateControls).catch(huddleShowError);}
function huddleScheduleRefresh(){if(!HUDDLE.refreshTimer&&HUDDLE.room)HUDDLE.refreshTimer=setTimeout(()=>{HUDDLE.refreshTimer=null;huddleRefresh();},300);}
async function huddleRefresh(){if(!HUDDLE.room||HUDDLE.refreshing)return;HUDDLE.refreshing=true;const epoch=HUDDLE.epoch,sid=HUDDLE.context.session.id;try{const result=await huddleApi('context',{sessionId:sid});if(epoch!==HUDDLE.epoch||HUDDLE.key!==huddleKey())return;HUDDLE.context=result.context;if(result.context.mic_locked&&HUDDLE.room.localParticipant.isMicrophoneEnabled)await HUDDLE.room.localParticipant.setMicrophoneEnabled(false);huddleUpdatePeople();huddleSyncTracks();huddleUpdateCollaboration();huddleUpdateControls();}catch(error){if(epoch===HUDDLE.epoch){if(error.status===403){huddleReset();HUDDLE.error=huddleMessage(error);if(S.page==='Huddle')render();}else huddleShowError(error);}}finally{if(epoch===HUDDLE.epoch)HUDDLE.refreshing=false;}}
async function huddleModerate(command,target=null){if(!HUDDLE.context?.is_host||HUDDLE.acting)return;HUDDLE.acting=true;huddleUpdateControls();const epoch=HUDDLE.epoch;try{const result=await huddleApi('moderate',{sessionId:HUDDLE.context.session.id,command,target});if(epoch===HUDDLE.epoch){HUDDLE.context=result.context;huddleUpdatePeople();huddleUpdateControls();}}catch(error){if(epoch===HUDDLE.epoch)huddleShowError(error);}finally{HUDDLE.acting=false;huddleUpdateControls();}}
function huddleTab(tab){HUDDLE.tab=tab;document.querySelectorAll('[data-huddle-pane]').forEach(n=>n.hidden=n.dataset.huddlePane!==tab);document.querySelectorAll('[data-huddle-tab]').forEach(n=>n.classList.toggle('active',n.dataset.huddleTab===tab));}
function huddleDataCard(data){return `<article class="huddle-data-card"><h3>${e(data.unit)}</h3><dl><div><dt>Active members</dt><dd>${e(data.members)}</dd></div><div><dt>Verified records</dt><dd>${e(data.verified_records)}</dd></div><div><dt>Savings</dt><dd>${money(data.savings)}</dd></div><div><dt>Share capital</dt><dd>${money(data.share_capital)}</dd></div><div><dt>Outstanding loans</dt><dd>${money(data.loans)}</dd></div><div><dt>Active loans</dt><dd>${e(data.active_loans)}</dd></div></dl><small>Snapshot ${e(new Date(data.as_of).toLocaleString('en-PH'))}</small></article>`;}
async function huddleLoadData(form){const epoch=HUDDLE.epoch;try{const unit=huddleUnit(form.elements.unit.value),result=await huddleApi('summary',{sessionId:HUDDLE.context.session.id,...unit});if(epoch!==HUDDLE.epoch)return;HUDDLE.data={...unit,summary:result.summary};huddleUpdateCollaboration();}catch(error){if(epoch===HUDDLE.epoch)huddleShowError(error);}}
async function huddleShareData(){if(!HUDDLE.data||!HUDDLE.context)return;const epoch=HUDDLE.epoch;try{const result=await huddleApi('share',{sessionId:HUDDLE.context.session.id,branch:HUDDLE.data.branch,district:HUDDLE.data.district});if(epoch===HUDDLE.epoch){HUDDLE.context=result.context;huddleUpdateCollaboration();toast('Data card shared with authorized staff.');}}catch(error){if(epoch===HUDDLE.epoch)huddleShowError(error);}}
function huddleUpdateCollaboration(){const c=HUDDLE.context;if(!c)return;const chat=document.querySelector('[data-huddle-chat]'),signature=JSON.stringify(c.messages);if(chat&&(HUDDLE.chatSignature!==signature||chat.dataset.initialized!=='true')){chat.innerHTML=c.messages.map(m=>`<article><div><strong>${e(m.sender_name)}</strong><time>${e(new Date(m.created_at).toLocaleTimeString('en-PH',{hour:'2-digit',minute:'2-digit'}))}</time></div><p>${e(m.body)}</p></article>`).join('')||'<p class="hint">Start the conversation.</p>';chat.dataset.initialized='true';HUDDLE.chatSignature=signature;chat.scrollTop=chat.scrollHeight;}const preview=document.querySelector('[data-huddle-data]');if(preview)preview.innerHTML=HUDDLE.data?huddleDataCard(HUDDLE.data.summary)+'<button type="button" class="primary small" onclick="huddleShareData()">Share data card</button>':'';const cards=document.querySelector('[data-huddle-shared]');if(cards)cards.innerHTML=c.cards.map(card=>huddleDataCard(card.summary)).join('')||'<p class="hint">No shared data for your assigned units.</p>';}
async function huddleSendChat(form){const button=form.querySelector('button'),message=form.elements.message.value,epoch=HUDDLE.epoch;button.disabled=true;try{const result=await huddleApi('chat',{sessionId:HUDDLE.context.session.id,message});if(epoch===HUDDLE.epoch){HUDDLE.context=result.context;if(form.elements.message.value===message)form.elements.message.value='';huddleUpdateCollaboration();}}catch(error){if(epoch===HUDDLE.epoch)huddleShowError(error);}finally{button.disabled=false;}}
function huddleInvitationUrl(session){const invite=new URL(location.origin+location.pathname);invite.hash='huddle='+session.id;return invite.href;}
async function huddleCopyInvitation(session){if(!session?.join_code)return;const invite=huddleInvitationUrl(session);try{await navigator.clipboard.writeText(`Join OCCCI Huddle: ${session.title}\n${invite}\nSession code: ${huddleCode(session.join_code)}`);toast('Invitation copied.');}catch{openModal('Huddle invitation',`<label>Session portal<input readonly value="${e(invite)}" onclick="this.select()"></label><label class="spacer">Special code<input readonly value="${e(huddleCode(session.join_code))}" onclick="this.select()"></label>`);}}
function huddleCopyInvite(){if(HUDDLE.context?.is_host)return huddleCopyInvitation(HUDDLE.context.session);}
function huddleCopySessionInvite(sid){const session=HUDDLE.sessions.find(s=>s.id===sid&&s.is_host);if(session)return huddleCopyInvitation(session);}
function huddleEndDialog(sid=HUDDLE.context?.session.id){const session=HUDDLE.sessions.find(s=>s.id===sid&&s.is_host)||(HUDDLE.context?.is_host&&HUDDLE.context.session.id===sid?HUDDLE.context.session:null);if(!session)return;openModal('End OCCCI Huddle',`<p>End <strong>${e(session.title)}</strong> and disconnect its attendees?</p><button type="button" class="danger" data-huddle-session="${e(sid)}" onclick="huddleEnd(this.dataset.huddleSession)">End session for everyone</button>`);}
async function huddleEnd(sid=HUDDLE.context?.session.id){if(!sid||HUDDLE.acting)return;HUDDLE.acting=true;const epoch=HUDDLE.epoch;try{await huddleApi('end',{sessionId:sid});if(epoch!==HUDDLE.epoch)return;if(HUDDLE.context?.session.id===sid)huddleReset();else{HUDDLE.sessions=HUDDLE.sessions.filter(s=>s.id!==sid);HUDDLE.sessionRevision++;huddleUpdateSessionPanel();}closeModal();if(S.page==='Huddle')render();toast('Huddle session ended.');}catch(error){if(epoch===HUDDLE.epoch){const message=document.getElementById('actionMessage');if(message)message.textContent=huddleMessage(error);else huddleShowError(error);}}finally{HUDDLE.acting=false;}}
async function huddleLeave(){const sid=HUDDLE.context?.session.id;huddleReset();if(S.page==='Huddle')render();if(sid)try{await huddleApi('leave',{sessionId:sid});}catch{/* Media is already stopped even if the connection dropped. */}}
function huddleReset(){HUDDLE.epoch++;clearInterval(HUDDLE.poll);clearInterval(HUDDLE.lobbyPoll);clearTimeout(HUDDLE.refreshTimer);HUDDLE.poll=null;HUDDLE.lobbyPoll=null;HUDDLE.refreshTimer=null;const room=HUDDLE.room;HUDDLE.room=null;for(const item of HUDDLE.attachments.values()){item.track.detach(item.element);item.element.remove();}HUDDLE.attachments.clear();if(room)Promise.resolve(room.disconnect(true)).catch(()=>{});document.getElementById('huddleAudio')?.remove();document.getElementById('huddleDock')?.remove();HUDDLE.context=null;HUDDLE.data=null;HUDDLE.view='sessions';HUDDLE.tab='attendees';HUDDLE.dataUnit='';HUDDLE.key='';HUDDLE.code='';HUDDLE.title='';HUDDLE.selectedSession='';HUDDLE.selectedTitle='';HUDDLE.busy=false;HUDDLE.acting=false;HUDDLE.loaded=false;HUDDLE.databaseReady=false;HUDDLE.permissions=null;HUDDLE.setupRequired=false;HUDDLE.configLoading=false;HUDDLE.listLoading=false;HUDDLE.sessions=[];HUDDLE.sessionRevision++;HUDDLE.panelSignature='';HUDDLE.error='';HUDDLE.refreshing=false;}
function huddleInitialize(){const check=()=>{const value=new URLSearchParams(location.hash.slice(1)).get('huddle');if(!value)return;if(/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(value)){HUDDLE.pendingSession=value;HUDDLE.pendingCode='';}else if(/^[a-z0-9 -]{8,24}$/i.test(value)){HUDDLE.pendingCode=value;HUDDLE.pendingSession='';}else return;if(huddleCanJoin())huddleMount();};check();window.addEventListener('hashchange',check);window.addEventListener('pagehide',huddleReset);}
